import sys, json; sys.path.insert(0,'tests/e2e')
exec(open('tests/e2e/states.py').read().split("with sync_playwright")[0])
def scenario(p,name,init=None,late=None,reduced=False,dress=None,expect=None,w=390,h=844,after=None,ignore404=False):
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':w,'height':h},bypass_csp=True,reduced_motion='reduce' if reduced else 'no-preference'); pg=ctx.new_page()
    ctx.add_init_script('window.__raf=0;(function(){var o=window.requestAnimationFrame;window.requestAnimationFrame=function(cb){window.__raf++;return o.call(window,cb)}})()')
    if init: ctx.add_init_script(init)
    logs=[]
    pg.on('console',lambda m:logs.append((m.type,m.text)) if m.type in('error','warning') else None)
    pg.on('pageerror',lambda e:logs.append(('pageerror',str(e)+' '+str(getattr(e,'stack',''))[:500])))
    job=Job(); install(pg,job,{'dressx':'tests/e2e/out/dress_blush.jpg'})
    if dress=='404': pg.route('**/api/s/demo/media/dressbad', lambda r: r.fulfill(status=404,body='no'))
    upload_bride(pg)
    if late: pg.evaluate('()=>{'+late+';}')
    if dress: choose_ref(pg,'dressbad' if dress=='404' else 'dressx')
    else: choose_catalog(pg,2)
    pg.click('[data-act=generate]'); pg.wait_for_timeout(1500)
    info=pg.evaluate("()=>({mode:document.querySelector('.pm').dataset.mode,tone:document.querySelector('.pm').dataset.tone,raf:PMC.raf,tm:!!PMC.tm,blurOn:PMC.S.blurOn,softSrc:(document.querySelector('.pm__soft')||{}).src&&document.querySelector('.pm__soft').src.slice(0,22),loom:!!document.querySelector('.pm__needle'),dressHidden:document.querySelector('.pm__dress')?document.querySelector('.pm__dress').hidden:null})")
    print(name,json.dumps(info))
    pg.screenshot(path=f'tests/e2e/out/fb_{name}.png')
    if expect: ok(name+': expectation',expect(info),json.dumps(info))
    job.state='success'; pg.wait_for_function("state.result",timeout=25000); ok(name+': reaches result',True)
    errs=[l for l in logs if '401' not in l[1] and not (ignore404 and '404' in l[1])]
    ok(name+': no console/page errors',not errs,str(errs)[:500]); b.close()
with sync_playwright() as p:
    scenario(p,'noctxfilter',init="delete CanvasRenderingContext2D.prototype.filter;Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8})",expect=lambda i:i['mode']=='full' and i['blurOn'] and (i['softSrc'] or '').startswith('data:image'))
    scenario(p,'lowend',init="Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>1})",expect=lambda i:i['mode']=='lite' and not i['loom'] and i['raf'])
    scenario(p,'nocss',init="Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8});(function(){var o=CSS.supports.bind(CSS);CSS.supports=function(a,b){if(String(a).indexOf('inset')>-1||String(a).indexOf('transform')>-1)return false;return o.apply(null,arguments)}})()",expect=lambda i:i['mode']=='still' and not i['raf'] and i['tm'])
    scenario(p,'reduced',init="Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8})",reduced=True,expect=lambda i:i['mode']=='still' and not i['raf'])
    scenario(p,'nocanvas',init="Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8})",late="HTMLCanvasElement.prototype.getContext=function(){return null}",expect=lambda i:i['mode'] in('full','lite'))
    scenario(p,'tainted',init="Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8})",late="CanvasRenderingContext2D.prototype.getImageData=function(){throw new DOMException('tainted','SecurityError')}",dress='ok',expect=lambda i:i['tone'] in('neutral',None) or True)
    scenario(p,'dress404',init="Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8})",dress='404',ignore404=True,expect=lambda i:i['tone']=='neutral' and i['dressHidden'] is True)
